import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

const reason = () => new Error('💥');

test('onIdle with an aborted signal rejects with the reason', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const error = reason();

	const job = limit(async () => {
		await delay(50);
	});

	const idlePromise = limit.onIdle({signal: controller.signal});
	controller.abort(error);

	await t.throwsAsync(idlePromise, {is: error});

	await job;
});

test('onIdle rejects a pre-aborted signal even when idle', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const error = reason();

	controller.abort(error);

	await t.throwsAsync(limit.onIdle({signal: controller.signal}), {is: error});
});

test('onIdle aborting does not cancel jobs', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	let finished = false;

	const job = limit(async () => {
		await delay(30);
		finished = true;
		return 'result';
	});

	const idlePromise = limit.onIdle({signal: controller.signal});
	controller.abort(reason());

	await t.throwsAsync(idlePromise);

	t.is(await job, 'result');
	t.true(finished);
});

test('onIdle aborting only rejects that waiter', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	const job = limit(async () => {
		await delay(30);
	});

	const abortedWaiter = limit.onIdle({signal: controller.signal});
	const otherWaiter = limit.onIdle();
	const noOptionsWaiter = limit.onIdle();

	controller.abort(reason());

	await t.throwsAsync(abortedWaiter);
	await otherWaiter;
	await noOptionsWaiter;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await job;
});

test('onIdle removing the abort listener allows settlement', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	limit(async () => delay(10));

	await limit.onIdle({signal: controller.signal});

	// Aborting after settlement must not throw or unhandled-reject.
	controller.abort(reason());

	t.pass();
});

test('onIdle abort after idle resolution does not reject other waiters', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	const job = limit(async () => {
		await delay(20);
	});

	const abortedWaiter = limit.onIdle({signal: controller.signal});
	const survivor = limit.onIdle();

	await job;
	await survivor;
	controller.abort(reason());

	await t.throwsAsync(abortedWaiter);
});

test('limitFunction.onIdle supports abort signals', async t => {
	const limitedFunction = limitFunction(async () => {
		await delay(30);
	}, {concurrency: 1});

	const controller = new AbortController();
	const error = reason();

	const first = limitedFunction();
	const idlePromise = limitedFunction.onIdle({signal: controller.signal});
	controller.abort(error);

	await t.throwsAsync(idlePromise, {is: error});
	await first;

	await limitedFunction.onIdle();
	t.pass();
});

test('limitFunction.onIdle rejects pre-aborted signal when idle', async t => {
	const limitedFunction = limitFunction(async () => 'ok', {concurrency: 1});
	const controller = new AbortController();
	const error = reason();

	controller.abort(error);

	await t.throwsAsync(limitedFunction.onIdle({signal: controller.signal}), {is: error});
});

test('onIdle preserves generic result with signal option', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	const job = limit(async () => 42);
	const idlePromise = limit.onIdle({signal: controller.signal});

	await idlePromise;
	t.is(await job, 42);
});

